package main

import (
	"fmt"
	"sync"
	"sync/atomic"
)

func main() {
	var counter int64
	var wg sync.WaitGroup
	for i := 0; i < 2; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < 1000; j++ {
				atomic.AddInt64(&counter, 1) // atomic: establishes ordering
			}
		}()
	}
	wg.Wait()
	fmt.Println(atomic.LoadInt64(&counter)) // always 2000, race-free
}

